sql.where:
o.deleted = 0

    AND o.order_no ILIKE '%' || #{q.keyword} || '%'


    AND o.warehouse_id = #{q.warehouseId}


    AND o.status = #{q.status}


    AND o.stocktake_type = #{q.stocktakeType}

mapper.select:
SELECT 
FROM wms_stocktake_order o
JOIN wms_warehouse w ON w.id = o.warehouse_id

${q.orderByClause}
LIMIT #{q.resolvedSize} OFFSET #{q.offset}

mapper.update:
UPDATE wms_stocktake_order
SET counted_locations = (
        SELECT count(DISTINCT location_id)
        FROM wms_stocktake_item
        WHERE stocktake_id = #{stocktakeId}
          AND counted_qty IS NOT NULL
    ),
    updated_at = now()
WHERE id = #{stocktakeId}

mapper.select:
SELECT COALESCE(sum(diff_qty), 0)
FROM wms_stocktake_item
WHERE stocktake_id = #{stocktakeId}
